[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <meta name="description" content="SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most.">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700;800&family=Rubik:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --purple-light: #9D6FFD;
      --purple-pale: #EDE5FC;
      --orange: #FF7A00;
      --orange-light: #FFA347;
      --orange-pale: #FFF0E0;
      --bg: #FAFAFA;
      --bg-white: #FFFFFF;
      --text-primary: #1E293B;
      --text-secondary: #475569;
      --text-muted: #94A3B8;
      --border: #E2E8F0;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 20px;
      --radius-xl: 28px;
      --radius-full: 9999px;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 30px rgba(0,0,0,0.1);
      --font-heading: 'Outfit', sans-serif;
      --font-body: 'Rubik', sans-serif;
      --transition-fast: 200ms ease;
      --transition-normal: 300ms ease;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font-body);
      background: var(--bg);
      color: var(--text-primary);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    @media (prefers-reduced-motion: reduce) {
      html { scroll-behavior: auto; }
      *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
    }

    /* ===== HEADER ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      transition: background var(--transition-fast);
    }

    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      height: 64px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: 1.5rem;
      color: var(--black);
      text-decoration: none;
      letter-spacing: -0.02em;
    }

    .logo span {
      background: linear-gradient(135deg, var(--purple), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .header-nav {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .header-nav a {
      font-family: var(--font-body);
      font-weight: 500;
      font-size: 0.938rem;
      color: var(--text-secondary);
      text-decoration: none;
      transition: color var(--transition-fast);
    }

    .header-nav a:hover, .header-nav a:focus-visible {
      color: var(--purple);
    }

    .header-nav a:focus-visible {
      outline: 2px solid var(--purple);
      outline-offset: 4px;
      border-radius: 2px;
    }

    .btn-login {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      font-family: var(--font-body);
      font-weight: 600;
      font-size: 0.875rem;
      padding: 10px 24px;
      background: var(--black);
      color: #fff;
      border: none;
      border-radius: var(--radius-full);
      cursor: pointer;
      text-decoration: none;
      transition: opacity var(--transition-fast), transform var(--transition-fast);
    }

    .btn-login:hover { opacity: 0.85; }
    .btn-login:active { transform: scale(0.97); }
    .btn-login:focus-visible { outline: 2px solid var(--purple); outline-offset: 3px; }

    /* Hamburger */
    .hamburger {
      display: none;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      width: 44px;
      height: 44px;
      background: none;
      border: none;
      cursor: pointer;
      padding: 0;
      gap: 5px;
      -webkit-tap-highlight-color: transparent;
    }

    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--black);
      border-radius: 2px;
      transition: transform var(--transition-normal), opacity var(--transition-fast);
    }

    .hamburger.active span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    .hamburger:focus-visible { outline: 2px solid var(--purple); outline-offset: 2px; border-radius: 4px; }

    /* Mobile nav overlay */
    .mobile-nav {
      display: none;
      position: fixed;
      top: 64px;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(255,255,255,0.98);
      backdrop-filter: blur(8px);
      -webkit-backdrop-filter: blur(8px);
      z-index: 99;
      padding: 32px 24px;
      flex-direction: column;
      gap: 8px;
      opacity: 0;
      transform: translateY(-8px);
      transition: opacity var(--transition-normal), transform var(--transition-normal);
    }

    .mobile-nav.open {
      display: flex;
      opacity: 1;
      transform: translateY(0);
    }

    .mobile-nav a {
      font-family: var(--font-body);
      font-weight: 500;
      font-size: 1.125rem;
      color: var(--text-primary);
      text-decoration: none;
      padding: 14px 0;
      border-bottom: 1px solid var(--border);
      transition: color var(--transition-fast);
    }

    .mobile-nav a:last-child { border-bottom: none; }
    .mobile-nav a:hover, .mobile-nav a:focus-visible { color: var(--purple); }
    .mobile-nav a:focus-visible { outline: 2px solid var(--purple); outline-offset: 2px; border-radius: 2px; }

    @media (max-width: 768px) {
      .header-nav { display: none; }
      .hamburger { display: flex; }
    }

    /* ===== HERO ===== */
    .hero {
      position: relative;
      min-height: 560px;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 120px 24px 80px;
      overflow: hidden;
      background: linear-gradient(135deg, #F5F0FF 0%, #FFF5EB 50%, #FDE8D8 100%);
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -120px;
      right: -80px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(118,56,250,0.15) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -60px;
      left: -60px;
      width: 300px;
      height: 300px;
      background: radial-gradient(circle, rgba(255,122,0,0.12) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }

    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 820px;
      text-align: center;
    }

    .hero h1 {
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: clamp(2.25rem, 5.5vw, 3.75rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
      color: var(--black);
      margin-bottom: 20px;
    }

    .hero h1 .gradient-text {
      background: linear-gradient(135deg, var(--purple), var(--orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero p {
      font-size: clamp(1rem, 2vw, 1.25rem);
      color: var(--text-secondary);
      max-width: 560px;
      margin: 0 auto 36px;
      line-height: 1.6;
    }

    .btn-cta {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      font-family: var(--font-body);
      font-weight: 600;
      font-size: 1.063rem;
      padding: 16px 40px;
      background: linear-gradient(135deg, var(--purple), #9333EA);
      color: #fff;
      border: none;
      border-radius: var(--radius-full);
      cursor: pointer;
      text-decoration: none;
      box-shadow: 0 4px 20px rgba(118,56,250,0.35);
      transition: transform var(--transition-fast), box-shadow var(--transition-fast);
    }

    .btn-cta:hover { transform: translateY(-2px); box-shadow: 0 6px 28px rgba(118,56,250,0.45); }
    .btn-cta:active { transform: translateY(0); }
    .btn-cta:focus-visible { outline: 2px solid var(--orange); outline-offset: 3px; }

    .btn-cta svg { width: 18px; height: 18px; }

    /* ===== SECTION UTILITY ===== */
    .section { padding: 80px 24px; }
    .section-inner { max-width: 1120px; margin: 0 auto; }

    /* ===== FEATURES ===== */
    .features {
      background: var(--bg-white);
    }

    .features .section-inner {
      display: flex;
      align-items: center;
      gap: 60px;
    }

    .features-visual {
      flex: 0 0 360px;
      height: 360px;
      border-radius: var(--radius-xl);
      background: linear-gradient(135deg, var(--purple-pale), #F3E8FF);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .features-visual::before {
      content: '';
      position: absolute;
      width: 180px;
      height: 180px;
      background: linear-gradient(135deg, var(--purple), var(--purple-light));
      border-radius: var(--radius-lg);
      transform: rotate(-12deg);
      opacity: 0.85;
    }

    .features-visual::after {
      content: '';
      position: absolute;
      width: 120px;
      height: 120px;
      background: linear-gradient(135deg, var(--orange), var(--orange-light));
      border-radius: var(--radius-lg);
      transform: rotate(8deg);
      top: 50px;
      right: 40px;
      opacity: 0.8;
    }

    .features-visual-icon {
      position: relative;
      z-index: 1;
    }

    .features-text { flex: 1; }

    .features-text h2 {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: clamp(1.75rem, 3.5vw, 2.5rem);
      line-height: 1.15;
      letter-spacing: -0.02em;
      color: var(--black);
      margin-bottom: 20px;
    }

    .features-text p {
      font-size: 1.063rem;
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: 28px;
    }

    .link-arrow {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-family: var(--font-body);
      font-weight: 600;
      font-size: 1rem;
      color: var(--purple);
      text-decoration: none;
      transition: gap var(--transition-fast), color var(--transition-fast);
      cursor: pointer;
    }

    .link-arrow:hover { gap: 10px; color: var(--purple-light); }
    .link-arrow:focus-visible { outline: 2px solid var(--purple); outline-offset: 3px; border-radius: 2px; }

    .link-arrow svg { width: 18px; height: 18px; transition: transform var(--transition-fast); }
    .link-arrow:hover svg { transform: translateX(2px); }

    .link-arrow-external { color: var(--orange); }
    .link-arrow-external:hover { color: var(--orange-light); }

    @media (max-width: 768px) {
      .features .section-inner { flex-direction: column; gap: 32px; }
      .features-visual { flex: none; width: 100%; max-width: 320px; height: 260px; }
    }

    /* ===== SAFETY ===== */
    .safety {
      background: linear-gradient(135deg, #F0F7FF 0%, #F5F0FF 100%);
    }

    .safety .section-inner {
      display: flex;
      align-items: center;
      gap: 60px;
    }

    .safety-visual {
      flex: 0 0 360px;
      height: 360px;
      border-radius: var(--radius-xl);
      background: linear-gradient(135deg, #E0F2FE, #DBEAFE);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .safety-visual::before {
      content: '';
      position: absolute;
      width: 140px;
      height: 140px;
      background: rgba(59,130,246,0.15);
      border-radius: 50%;
    }

    .safety-visual::after {
      content: '';
      position: absolute;
      width: 80px;
      height: 80px;
      border: 3px solid rgba(59,130,246,0.2);
      border-radius: 50%;
      bottom: 60px;
      right: 50px;
    }

    .safety-text { flex: 1; }

    .safety-text h2 {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: clamp(1.75rem, 3.5vw, 2.5rem);
      line-height: 1.15;
      letter-spacing: -0.02em;
      color: var(--black);
      margin-bottom: 20px;
    }

    .safety-text p {
      font-size: 1.063rem;
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: 28px;
    }

    @media (max-width: 768px) {
      .safety .section-inner { flex-direction: column-reverse; gap: 32px; }
      .safety-visual { flex: none; width: 100%; max-width: 320px; height: 260px; }
    }

    /* ===== CREATORS ===== */
    .creators {
      background: var(--bg-white);
    }

    .creators .section-inner {
      display: flex;
      align-items: center;
      gap: 60px;
    }

    .creators-visual {
      flex: 0 0 360px;
      height: 360px;
      border-radius: var(--radius-xl);
      background: linear-gradient(135deg, var(--orange-pale), #FFE4C9);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .creators-visual::before {
      content: '';
      position: absolute;
      width: 200px;
      height: 200px;
      background: linear-gradient(135deg, var(--orange), var(--orange-light));
      border-radius: 40% 60% 70% 30% / 40% 50% 60% 50%;
      opacity: 0.7;
    }

    .creators-visual::after {
      content: '';
      position: absolute;
      width: 100px;
      height: 100px;
      background: linear-gradient(135deg, var(--purple), var(--purple-light));
      border-radius: 50%;
      bottom: 40px;
      left: 40px;
      opacity: 0.6;
    }

    .creators-text { flex: 1; }

    .creators-text h2 {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: clamp(1.75rem, 3.5vw, 2.5rem);
      line-height: 1.15;
      letter-spacing: -0.02em;
      color: var(--black);
      margin-bottom: 20px;
    }

    .creators-text p {
      font-size: 1.063rem;
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: 28px;
    }

    @media (max-width: 768px) {
      .creators .section-inner { flex-direction: column; gap: 32px; }
      .creators-visual { flex: none; width: 100%; max-width: 320px; height: 260px; }
    }

    /* ===== TAGLINE BANNER ===== */
    .tagline-banner {
      background: linear-gradient(135deg, var(--purple) 0%, #9333EA 40%, var(--orange) 100%);
      padding: 64px 24px;
      text-align: center;
    }

    .tagline-banner h2 {
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: clamp(1.5rem, 4vw, 2.75rem);
      color: #fff;
      letter-spacing: -0.02em;
      line-height: 1.2;
    }

    /* ===== NEWS ===== */
    .news {
      background: var(--bg);
      padding: 80px 0;
    }

    .news-header {
      max-width: 1120px;
      margin: 0 auto;
      padding: 0 24px;
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: 40px;
    }

    .news-label {
      font-family: var(--font-body);
      font-weight: 600;
      font-size: 0.813rem;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--purple);
      margin-bottom: 8px;
    }

    .news-header h2 {
      font-family: var(--font-heading);
      font-weight: 700;
      font-size: clamp(1.5rem, 3vw, 2.25rem);
      color: var(--black);
      letter-spacing: -0.02em;
    }

    .news-view-more {
      font-family: var(--font-body);
      font-weight: 600;
      font-size: 0.938rem;
      color: var(--purple);
      text-decoration: none;
      white-space: nowrap;
      transition: color var(--transition-fast);
      cursor: pointer;
    }

    .news-view-more:hover { color: var(--purple-light); }
    .news-view-more:focus-visible { outline: 2px solid var(--purple); outline-offset: 3px; border-radius: 2px; }

    .news-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding: 4px 24px 24px;
      scrollbar-width: thin;
      scrollbar-color: var(--border) transparent;
    }

    .news-carousel::-webkit-scrollbar { height: 6px; }
    .news-carousel::-webkit-scrollbar-track { background: transparent; }
    .news-carousel::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
    .news-carousel::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

    .news-card {
      flex: 0 0 320px;
      scroll-snap-align: start;
      background: var(--bg-white);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border);
      overflow: hidden;
      transition: transform var(--transition-fast), box-shadow var(--transition-fast);
      cursor: pointer;
    }

    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .news-card:focus-within {
      outline: 2px solid var(--purple);
      outline-offset: 2px;
    }

    .news-card-thumb {
      width: 100%;
      height: 180px;
      background: linear-gradient(135deg, var(--purple-pale), var(--orange-pale));
      position: relative;
      overflow: hidden;
    }

    .news-card-thumb::before {
      content: '';
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      height: 50%;
      background: linear-gradient(to top, rgba(0,0,0,0.03), transparent);
    }

    .news-card-thumb-icon {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      opacity: 0.25;
    }

    .news-card-body {
      padding: 20px;
    }

    .news-card-tags {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
      margin-bottom: 12px;
    }

    .tag-pill {
      font-family: var(--font-body);
      font-weight: 600;
      font-size: 0.688rem;
      text-transform: uppercase;
      letter-spacing: 0.04em;
      padding: 4px 10px;
      border-radius: var(--radius-full);
      background: var(--purple-pale);
      color: var(--purple);
    }

    .tag-pill.orange {
      background: var(--orange-pale);
      color: var(--orange);
    }

    .tag-pill.blue {
      background: #E0F2FE;
      color: #0369A1;
    }

    .news-card-title {
      font-family: var(--font-heading);
      font-weight: 600;
      font-size: 1rem;
      line-height: 1.4;
      color: var(--text-primary);
      margin-bottom: 10px;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .news-card-date {
      font-family: var(--font-body);
      font-size: 0.813rem;
      color: var(--text-muted);
    }

    @media (max-width: 768px) {
      .news-card { flex: 0 0 280px; }
      .news-card-thumb { height: 150px; }
    }

    /* ===== CTA DOWNLOAD ===== */
    .cta-download {
      background: linear-gradient(135deg, #1a0030 0%, #2d0a4e 40%, #1a0030 100%);
      padding: 80px 24px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .cta-download::before {
      content: '';
      position: absolute;
      top: -100px;
      right: -100px;
      width: 300px;
      height: 300px;
      background: radial-gradient(circle, rgba(118,56,250,0.3) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }

    .cta-download::after {
      content: '';
      position: absolute;
      bottom: -80px;
      left: -80px;
      width: 250px;
      height: 250px;
      background: radial-gradient(circle, rgba(255,122,0,0.2) 0%, transparent 70%);
      border-radius: 50%;
      pointer-events: none;
    }

    .cta-download h2 {
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: clamp(2rem, 4.5vw, 3rem);
      color: #fff;
      letter-spacing: -0.02em;
      margin-bottom: 8px;
      position: relative;
      z-index: 1;
    }

    .cta-download .sub {
      font-family: var(--font-body);
      font-size: 1.25rem;
      color: rgba(255,255,255,0.7);
      margin-bottom: 36px;
      position: relative;
      z-index: 1;
    }

    .cta-buttons {
      display: flex;
      justify-content: center;
      gap: 16px;
      flex-wrap: wrap;
      position: relative;
      z-index: 1;
    }

    .btn-store {
      display: inline-flex;
      align-items: center;
      gap: 12px;
      padding: 14px 28px;
      background: #fff;
      color: var(--black);
      border: none;
      border-radius: var(--radius-md);
      cursor: pointer;
      font-family: var(--font-body);
      transition: transform var(--transition-fast), box-shadow var(--transition-fast);
    }

    .btn-store:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,0,0,0.3); }
    .btn-store:active { transform: translateY(0); }
    .btn-store:focus-visible { outline: 2px solid var(--orange); outline-offset: 3px; }

    .btn-store svg { width: 28px; height: 28px; flex-shrink: 0; }

    .btn-store-text { text-align: left; }
    .btn-store-text .small { font-size: 0.688rem; color: var(--text-muted); display: block; line-height: 1; }
    .btn-store-text .big { font-size: 1.063rem; font-weight: 700; line-height: 1.2; }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--black);
      color: rgba(255,255,255,0.8);
      padding: 64px 24px 0;
    }

    .footer-inner {
      max-width: 1120px;
      margin: 0 auto;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 32px;
      padding-bottom: 48px;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }

    .footer-col h3 {
      font-family: var(--font-heading);
      font-weight: 600;
      font-size: 0.938rem;
      color: #fff;
      margin-bottom: 16px;
      letter-spacing: -0.01em;
    }

    .footer-col ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .footer-col a {
      font-family: var(--font-body);
      font-size: 0.875rem;
      color: rgba(255,255,255,0.6);
      text-decoration: none;
      transition: color var(--transition-fast);
      display: inline-flex;
      align-items: center;
      gap: 4px;
    }

    .footer-col a:hover { color: #fff; }
    .footer-col a:focus-visible { outline: 1px solid var(--purple); outline-offset: 2px; border-radius: 2px; }

    .external-icon {
      width: 12px;
      height: 12px;
      opacity: 0.5;
    }

    .footer-bottom {
      padding: 28px 0;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-lang {
      font-family: var(--font-body);
      font-size: 0.813rem;
      color: rgba(255,255,255,0.5);
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .footer-lang select {
      background: rgba(255,255,255,0.08);
      color: rgba(255,255,255,0.7);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: var(--radius-sm);
      padding: 6px 10px;
      font-family: var(--font-body);
      font-size: 0.813rem;
      cursor: pointer;
    }

    .footer-lang select:focus-visible { outline: 1px solid var(--purple); }

    .footer-socials {
      display: flex;
      gap: 16px;
    }

    .footer-socials a {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 36px;
      height: 36px;
      border-radius: 50%;
      color: rgba(255,255,255,0.5);
      transition: color var(--transition-fast), background var(--transition-fast);
    }

    .footer-socials a:hover { color: #fff; background: rgba(255,255,255,0.08); }
    .footer-socials a:focus-visible { outline: 1px solid var(--purple); outline-offset: 2px; }
    .footer-socials svg { width: 18px; height: 18px; }

    .footer-legal {
      display: flex;
      gap: 20px;
      flex-wrap: wrap;
    }

    .footer-legal a {
      font-family: var(--font-body);
      font-size: 0.75rem;
      color: rgba(255,255,255,0.4);
      text-decoration: none;
      transition: color var(--transition-fast);
    }

    .footer-legal a:hover { color: rgba(255,255,255,0.7); }
    .footer-legal a:focus-visible { outline: 1px solid var(--purple); outline-offset: 2px; border-radius: 2px; }

    .footer-legal span {
      color: rgba(255,255,255,0.2);
      font-size: 0.75rem;
    }

    @media (max-width: 768px) {
      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 28px;
      }
      .footer-bottom { flex-direction: column; align-items: flex-start; }
    }

    @media (max-width: 480px) {
      .footer-grid { grid-template-columns: 1fr; gap: 24px; }
    }

    /* ===== SKIP LINK ===== */
    .skip-link {
      position: absolute;
      top: -100%;
      left: 16px;
      background: var(--purple);
      color: #fff;
      padding: 12px 24px;
      border-radius: var(--radius-sm);
      font-weight: 600;
      z-index: 200;
      text-decoration: none;
    }

    .skip-link:focus { top: 16px; }

    /* ===== UTILITY ===== */
    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0,0,0,0);
      white-space: nowrap;
      border: 0;
    }

    /* Carousel drag cursor */
    .news-carousel.dragging { cursor: grabbing; }
    .news-carousel:not(.dragging) { cursor: grab; }
    .news-carousel.dragging .news-card { pointer-events: none; }
  </style>
</head>
