  <script>
    // ===== HAMBURGER MENU =====
    (function() {
      var hamburger = document.getElementById('hamburger');
      var mobileNav = document.getElementById('mobile-nav');
      var isOpen = false;

      function toggleMenu() {
        isOpen = !isOpen;
        hamburger.classList.toggle('active', isOpen);
        hamburger.setAttribute('aria-expanded', isOpen);
        if (isOpen) {
          mobileNav.classList.add('open');
          document.body.style.overflow = 'hidden';
          // Focus first link for accessibility
          var firstLink = mobileNav.querySelector('a');
          if (firstLink) firstLink.focus();
        } else {
          mobileNav.classList.remove('open');
          document.body.style.overflow = '';
          hamburger.focus();
        }
      }

      hamburger.addEventListener('click', toggleMenu);

      // Close on link click
      mobileNav.querySelectorAll('a').forEach(function(link) {
        link.addEventListener('click', function() {
          if (isOpen) toggleMenu();
        });
      });

      // Close on Escape
      document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && isOpen) toggleMenu();
      });
    })();

    // ===== NEWS CAROUSEL — drag to scroll =====
    (function() {
      var carousel = document.getElementById('newsCarousel');
      var isDragging = false;
      var startX = 0;
      var scrollLeft = 0;

      carousel.addEventListener('mousedown', function(e) {
        isDragging = true;
        carousel.classList.add('dragging');
        startX = e.pageX - carousel.offsetLeft;
        scrollLeft = carousel.scrollLeft;
      });

      carousel.addEventListener('mouseleave', function() {
        if (isDragging) stopDrag();
      });

      carousel.addEventListener('mouseup', function() {
        if (isDragging) stopDrag();
      });

      carousel.addEventListener('mousemove', function(e) {
        if (!isDragging) return;
        e.preventDefault();
        var x = e.pageX - carousel.offsetLeft;
        var walk = (x - startX) * 1.5;
        carousel.scrollLeft = scrollLeft - walk;
      });

      function stopDrag() {
        isDragging = false;
        carousel.classList.remove('dragging');
      }

      // Touch: just let native scroll-snap handle it (already works)
      // Prevent card links from firing after drag
      carousel.addEventListener('click', function(e) {
        if (isDragging) e.preventDefault();
      }, true);
    })();

    // ===== KEYBOARD NAV FOR CAROUSEL =====
    (function() {
      var carousel = document.getElementById('newsCarousel');
      var cards = carousel.querySelectorAll('.news-card');

      cards.forEach(function(card, i) {
        card.addEventListener('keydown', function(e) {
          if (e.key === 'ArrowRight' && i < cards.length - 1) {
            e.preventDefault();
            cards[i + 1].focus();
            cards[i + 1].scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
          } else if (e.key === 'ArrowLeft' && i > 0) {
            e.preventDefault();
            cards[i - 1].focus();
            cards[i - 1].scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
          }
        });
      });
    })();
  </script>
